window.MANUAL_INDEX = [{"url":"appendices.html#glossary","title":"Glossary","section":"appendices","text":"Written in Phase 4."},{"url":"appendices.html#shortcuts","title":"Keyboard and mouse","section":"appendices","text":"Written in Phase 4."},{"url":"appendices.html#limits","title":"What this editor cannot do yet","section":"appendices","text":"Written in Phase 4."},{"url":"appendices.html#events-list","title":"The 92 events","section":"appendices","text":"Written in Phase 4."},{"url":"appendices.html#version","title":"Which handbook version is this","section":"appendices","text":"Written in Phase 4. ← When something goes wrong HackHub Quest Editor handbook · documents editor build 2026-09-14.r162 · every figure on these pages is taken from the editor's own source."},{"url":"checking.html#where-messages-appear","title":"Where messages appear","section":"checking","text":"Written in Phase 4."},{"url":"checking.html#levels","title":"The three levels","section":"checking","text":"Written in Phase 4."},{"url":"checking.html#msg-index","title":"Message index","section":"checking","text":"Written in Phase 4."},{"url":"checking.html#msg-unreachable","title":"Unreachable","section":"checking","text":"Written in Phase 4."},{"url":"checking.html#msg-no-trigger","title":"No trigger","section":"checking","text":"Written in Phase 4."},{"url":"checking.html#msg-dead-end","title":"Dead end","section":"checking","text":"Written in Phase 4."},{"url":"checking.html#msg-only-runs-on-completion","title":"Only runs on completion","section":"checking","text":"Written in Phase 4."},{"url":"checking.html#msg-empty","title":"Empty","section":"checking","text":"Written in Phase 4."},{"url":"checking.html#pre-export","title":"Before you export","section":"checking","text":"Written in Phase 4. ← How do I… Exporting and installing → HackHub Quest Editor handbook · documents editor build 2026-09-14.r162 · every figure on these pages is taken from the editor's own source."},{"url":"concepts.html#quest-map","title":"Your quest map","section":"concepts","text":"Written in Phase 4."},{"url":"concepts.html#lifecycle","title":"When your quest runs","section":"concepts","text":"Written in Phase 4."},{"url":"concepts.html#wire-kinds","title":"Wires have kinds","section":"concepts","text":"Written in Phase 4."},{"url":"concepts.html#objectives","title":"Objectives are how the player knows what to do","section":"concepts","text":"Written in Phase 4."},{"url":"concepts.html#events","title":"Events are how your quest hears the player","section":"concepts","text":"Written in Phase 4."},{"url":"concepts.html#what-export-means","title":"What exporting means","section":"concepts","text":"Written in Phase 4."},{"url":"concepts.html#permissions","title":"Permissions, in plain words","section":"concepts","text":"Written in Phase 4."},{"url":"concepts.html#why-no-complete","title":"Why quests do not complete","section":"concepts","text":"Written in Phase 4. ← Your first quest Node reference → HackHub Quest Editor handbook · documents editor build 2026-09-14.r162 · every figure on these pages is taken from the editor's own source."},{"url":"export.html#export-dialog","title":"The export dialog","section":"export","text":"Written in Phase 4."},{"url":"export.html#zip-contents","title":"What is inside the zip","section":"export","text":"Written in Phase 4."},{"url":"export.html#installing","title":"Installing it in the game","section":"export","text":"Written in Phase 4."},{"url":"export.html#export-is-not-a-save","title":"Export is not a save","section":"export","text":"Written in Phase 4."},{"url":"export.html#build-stamp","title":"The build stamp","section":"export","text":"Written in Phase 4. ← Checking your quest When something goes wrong → HackHub Quest Editor handbook · documents editor build 2026-09-14.r162 · every figure on these pages is taken from the editor's own source."},{"url":"guides.html#inspector-tabs","title":"The inspector's three tabs","section":"guides","text":"Written in Phase 4."},{"url":"guides.html#quest-settings","title":"Quest settings","section":"guides","text":"Written in Phase 4."},{"url":"guides.html#mod-settings","title":"Mod settings","section":"guides","text":"Written in Phase 4."},{"url":"guides.html#dialogues","title":"Dialogues","section":"guides","text":"Written in Phase 4."},{"url":"guides.html#websites","title":"Websites","section":"guides","text":"Written in Phase 4."},{"url":"guides.html#templates","title":"Templates","section":"guides","text":"Written in Phase 4."},{"url":"guides.html#dry-run","title":"Dry run","section":"guides","text":"Written in Phase 4."},{"url":"guides.html#addons","title":"Addons and Editor Mods","section":"guides","text":"Written in Phase 4."},{"url":"guides.html#settings","title":"Settings and preferences","section":"guides","text":"Written in Phase 4."},{"url":"guides.html#canvas-tools","title":"Canvas tools","section":"guides","text":"Written in Phase 4."},{"url":"guides.html#generate-tags","title":"Generate and tags","section":"guides","text":"Written in Phase 4. ← Node reference How do I… → HackHub Quest Editor handbook · documents editor build 2026-09-14.r162 · every figure on these pages is taken from the editor's own source."},{"url":"how-do-i.html","title":"How do I… — HackHub Quest Editor handbook How do I… Sixteen walkthroughs, each o","section":"how-do-i.html","text":"How do I… — HackHub Quest Editor handbook How do I… Sixteen walkthroughs, each one solving a single thing an author actually wants. These are not a feature of the editor. They are arrangements other authors have built, written out as steps you can follow. Each one names the nodes it uses, how long it takes, why the arrangement works, and the two or three ways it usually goes wrong. They are drawn from the built-in templates and from how the game's own quests are put together. Being written. This page is scaffolding from the Phase 3 skeleton — the structure and anchors are final, the prose land"},{"url":"index.html#contents-learn","title":"Learn it once","section":"index","text":"Your first quest Twenty minutes, start to finish, ending in a mod you install and play. How a quest works The mental model in eight short pieces the rest of the book keeps referring back to."},{"url":"index.html#contents-look","title":"Look things up","section":"index","text":"Node reference One page per node, every setting with its default, limits and what happens when you leave it empty. Grouped the way the palette groups them: Quest lifecycle Quest start · On start & reload · On quest complete · On quest abandoned Objectives Objective Triggers When event World building Create network · Firewall rule · Change port · Register domain · Create database · Place files · Tool response Communication Dialogue Custom terminal Manual input Effects Pay the player · Charge the player · Notify · Set quest data · Claim another quest · Run terminal command · Open handbook Community addons Give data to an addon · Addon node Flow control Branch · Wait · Reroute · Random pick · S"},{"url":"index.html#contents-fix","title":"When it goes sideways","section":"index","text":"Checking your quest Every message the editor can show you, searchable by pasting the exact text. When something goes wrong A decision tree that starts from the symptom, not the cause. Exporting and installing What the zip holds, where it goes, and how to update a quest you already shipped. Glossary and limits Every word, every key, and everything this editor cannot do yet. Three things worth knowing before you start A quest never completes on its own. That sounds like a bug and is worth understanding properly — why quests do not complete . Your editor settings are not part of the mod. Theme, font, grid and wire feel stay on your machine. See Settings . Exporting is not saving. The .zip is th"},{"url":"nodes/entry-abandon.html","title":"On quest abandoned — HackHub Quest Editor handbook On quest abandoned Quest life","section":"nodes/entry-abandon.html","text":"On quest abandoned — HackHub Quest Editor handbook On quest abandoned Quest lifecycle entry.abandon What it does Runs if the player abandons the quest. Use it to tidy up whatever the quest left behind. When you'd use it Reach for it when your quest changes the world in a way that should not outlive a quit: a machine left unlocked, a contact left waiting mid-conversation. Most quests do not need it. If nothing has to be undone, delete the node rather than leaving it sitting there empty. In the game, this looks like The player drops the quest and this fires. Anything you wired after it runs once"},{"url":"nodes/entry-complete.html","title":"On quest complete — HackHub Quest Editor handbook On quest complete Quest lifecy","section":"nodes/entry-complete.html","text":"On quest complete — HackHub Quest Editor handbook On quest complete Quest lifecycle entry.complete What it does Runs when the quest is marked complete. Under the default settings, that never happens. When you'd use it By default a quest has no way to complete. The player gets no Complete button, and auto-complete is off. So end your story from the last objective's On complete socket instead. That path always runs when the objective ticks over. Keep this node for the day you switch on auto-complete or add a completion button. Until then it sits there doing nothing. In the game, this looks like "},{"url":"nodes/entry-load.html","title":"On start & reload — HackHub Quest Editor handbook On start & reload Quest lifecy","section":"nodes/entry-load.html","text":"On start & reload — HackHub Quest Editor handbook On start & reload Quest lifecycle entry.load What it does Runs when the quest is claimed, and again every time the game loads it. Anything that has to be true in every session goes here. When you'd use it Put anything that watches for a player action here rather than in Quest start . A watcher armed once stops working after the player reloads. Use it for the pieces a returning player expects to still be working: the listeners behind your triggers, the state of a machine they left mid-job. Keep one-off story beats out of it. They belong in Quest"},{"url":"nodes/entry-start.html","title":"Quest start — HackHub Quest Editor handbook Quest start Quest lifecycle entry.st","section":"nodes/entry-start.html","text":"Quest start — HackHub Quest Editor handbook Quest start Quest lifecycle entry.start What it does Runs the moment the quest is claimed. Anything the story needs in place before the player acts goes here. When you'd use it This is the front door of your quest. Wire the opening to its Out socket: the briefing mail, the first objective, whatever the player should meet first. You can have more than one, and the game runs all of them when the quest is claimed. Splitting a long opening across two is fine. It has no input socket, because nothing runs before it. In the game, this looks like The player "},{"url":"nodes/flow-beat.html#node-flow-beat-field-title","title":"Headline","section":"nodes/flow-beat","text":"A short name for this beat, e.g. “Act 2 — the firewall”. It is the card's title bar. What to put here The card's title bar. Name the beat after the scene. Example Act 2 — the firewall Default empty If you leave it empty The card has no title, so on a crowded canvas you cannot tell one beat from another."},{"url":"nodes/flow-beat.html#node-flow-beat-field-text","title":"Beat text","section":"nodes/flow-beat","text":"The key content of the beat. The card previews the top ~800 characters and expands into a scrollable panel for the rest. What to put here What happens in the beat. The card previews the top of it and expands in the inspector. Default empty"},{"url":"nodes/flow-beat.html#node-flow-beat-field-choices","title":"Branch choices","section":"nodes/flow-beat","text":"Add a row for each path the story can take. Each gets its own output socket on the card, so you can wire each branch onward while planning. What to put here One row per path the story can take. Each row becomes an output socket on the card. Default an empty list The button reads Add choice ."},{"url":"nodes/flow-beat.html#node-flow-beat-field-label","title":"Choice","section":"nodes/flow-beat","text":"Short title for this path, e.g. “Go in through the front door”. What to put here A short title for the path. Example Go in through the front door"},{"url":"nodes/flow-beat.html#node-flow-beat-field-note","title":"What happens","section":"nodes/flow-beat","text":"One line on where this path leads, so a branching beat reads at a glance. What to put here One line on where this path leads, so a branching beat reads at a glance."},{"url":"nodes/flow-beat.html#node-flow-beat-field-width","title":"Width (px)","section":"nodes/flow-beat","text":"How wide the card is on the canvas, in pixels. Default 280 Limits 200 to 640. Whole numbers, in steps of 20."},{"url":"nodes/flow-beat.html#node-flow-beat-field-color","title":"Card colour","section":"nodes/flow-beat","text":"Pick any colour. Colour-coding by act, character or branch is usually the clearest. What to put here Colour the card by act, character or branch, so a big canvas reads at a glance. Default \"#64748b\" Wires Socket Direction What to connect In input Whatever should run immediately before this node. Out output Whatever should happen after this node runs. Then runs next When tests a condition Unlocks opens an objective Data carries a value A wire only joins two sockets of the same colour, and the editor draws the wire in that colour. That is what the colours are for: match the colours and the connection takes, mismatch them and it will not. The inspector for Story Beat . Common mistakes Expecting"},{"url":"nodes/flow-branch.html#node-flow-branch-field-source","title":"Test against","section":"nodes/flow-branch","text":"Test against details from the event that fired, or against quest data you stored earlier with a “Set quest data” node. What to put here Pick what the condition is tested against. <b class=\"ui\">Event</b> tests the details carried by the event that fired. <b class=\"ui\">Data</b> tests values you stored with <a href=\"fx-setdata.html\">Set quest data</a>. Default \"event\" Limits One of the 2 listed below. Watch out Pick <b class=\"ui\">Data</b> when the thing you are testing happened earlier in the quest. The event that woke this branch only carries its own details. Choice What it is stored as Details from the event event Quest data data"},{"url":"nodes/flow-branch.html#node-flow-branch-field-conditions","title":"Take the “Yes” path when","section":"nodes/flow-branch","text":"All clauses must hold for the “Yes” path. Otherwise the “No” path runs. What to put here Add one clause per thing that has to be true. Default an empty list If you leave it empty With no clauses there is nothing to fail, so the <b class=\"ui\">Yes</b> path always runs and the <b class=\"ui\">No</b> path never does. Wires Socket Direction What to connect In input Whatever should run immediately before the split. Trigger input The event that wakes the branch, when it should react to something the player does. Yes output Whatever should happen after this node runs. No output Whatever should happen after this node runs. Then runs next When tests a condition Unlocks opens an objective Data carries a "},{"url":"nodes/flow-debug.html#node-flow-debug-field-label","title":"Label","section":"nodes/flow-debug","text":"Names itself after whatever you wire it to — socket, node and detail. Type your own to override it. Default empty"},{"url":"nodes/flow-debug.html#node-flow-debug-field-includeData","title":"Include saved values","section":"nodes/flow-debug","text":"Print everything the quest has saved with a “Remember a value” node. What it does Print everything the quest has saved with a “Remember a value” node. Default on Limits On or off."},{"url":"nodes/flow-debug.html#node-flow-debug-field-includePayload","title":"Include the event","section":"nodes/flow-debug","text":"Also print the details the game passed to this point, so you can see the real values instead of guessing what arrived. What it does Also print the details the game passed to this point, so you can see the real values instead of guessing what arrived. Default on Limits On or off."},{"url":"nodes/flow-debug.html#node-flow-debug-field-toast","title":"Show on screen too","section":"nodes/flow-debug","text":"Also show it on screen, so you can test without reading the log file. What it does Also show it on screen, so you can test without reading the log file. Default off Limits On or off. Watch out Switch it off before you ship. Debug output a player can see shows them the seams. Wires Socket Direction What to connect In input Whatever should run immediately before this node. Out output Whatever should happen after this node runs. Then runs next When tests a condition Unlocks opens an objective Data carries a value A wire only joins two sockets of the same colour, and the editor draws the wire in that colour. That is what the colours are for: match the colours and the connection takes, mismatch t"},{"url":"nodes/flow-delay.html#node-flow-delay-field-seconds","title":"Seconds","section":"nodes/flow-delay","text":"How long the story pauses here. Fractions are fine — 0.5 waits half a second. Example 2 Default 1 Limits 0 or more. Steps of 0.5, so fractions that fine are allowed. If you leave it empty There is no pause. A blank value counts as zero and the story carries straight on. Wires Socket Direction What to connect In input Whatever should run immediately before this node. Out output Whatever should happen after this node runs. Then runs next When tests a condition Unlocks opens an objective Data carries a value A wire only joins two sockets of the same colour, and the editor draws the wire in that colour. That is what the colours are for: match the colours and the connection takes, mismatch them a"},{"url":"nodes/flow-note.html#node-flow-note-field-text","title":"Note","section":"nodes/flow-note","text":"Shown on the canvas only. Notes are never exported into the mod. Default empty"},{"url":"nodes/flow-note.html#node-flow-note-field-width","title":"Width","section":"nodes/flow-note","text":"How wide the note is on the canvas, in pixels. Default 240 Limits 160 to 640. Whole numbers, in steps of 20. Wires This node has no sockets of its own. Then runs next When tests a condition Unlocks opens an objective Data carries a value A wire only joins two sockets of the same colour, and the editor draws the wire in that colour. That is what the colours are for: match the colours and the connection takes, mismatch them and it will not. The inspector for Sticky note . Related nodes Group frame — A named box that moves its nodes. Story Beat — Plans a story beat. Never runs. ← Debug probe Story Beat → ↑ back to top HackHub Quest Editor handbook · documents editor build 2026-09-14.r162 · fiel"},{"url":"nodes/flow-random.html#node-flow-random-field-options","title":"Options","section":"nodes/flow-random","text":"One of these is picked at random and stored. Add as many as you like. What to put here The values to choose between. Add as many as you like. Default an empty list Watch out With one option there is nothing random about it. With none, there is nothing to pick. The button reads Add option ."},{"url":"nodes/flow-random.html#node-flow-random-field-label","title":"Value","section":"nodes/flow-random","text":"The value stored if this option is picked. What to put here The value stored if this option is the one picked."},{"url":"nodes/flow-random.html#node-flow-random-field-storeAs","title":"Store the result as","section":"nodes/flow-random","text":"A name you choose. The picked value is saved under it so you can read it back later with {{data.name}}. What to put here The name the picked value is stored under. Example guardOnDuty If you leave it empty The pick is not stored, so nothing can read it back later. Wires Socket Direction What to connect In input Whatever should run immediately before this node. Out output Whatever should happen after this node runs. Then runs next When tests a condition Unlocks opens an objective Data carries a value A wire only joins two sockets of the same colour, and the editor draws the wire in that colour. That is what the colours are for: match the colours and the connection takes, mismatch them and it "},{"url":"nodes/flow-reroute.html","title":"Reroute — HackHub Quest Editor handbook Reroute Flow control flow.reroute What i","section":"nodes/flow-reroute.html","text":"Reroute — HackHub Quest Editor handbook Reroute Flow control flow.reroute What it does A point to route wires through. It tidies the canvas and changes nothing about the story. When you'd use it Use it when one node has to feed several others, or when a wire would otherwise cross half the canvas. Double-click any wire on the canvas to drop one in automatically. In the game, this looks like Nothing. It changes how the canvas looks, not how the quest runs. Fields This node has nothing to configure. It marks a moment in the story and runs whatever is wired after it. Wires Socket Direction What to"},{"url":"nodes/flow-sequence.html#node-flow-sequence-field-steps","title":"Outputs, in order","section":"nodes/flow-sequence","text":"They fire top to bottom. Drag the rows' ✕ to remove an output — any wire attached to it is removed too. What to put here One row per output, in the order they should fire. Default a starter list Watch out Removing a row removes its socket, and any wire attached to it goes with it. The button reads Add output ."},{"url":"nodes/flow-sequence.html#node-flow-sequence-field-label","title":"Name","section":"nodes/flow-sequence","text":"Free text — whatever helps you recognise this output on the canvas, e.g. “lights out” or “call Mara”. What to put here A name for the output, so you can tell the sockets apart on the canvas."},{"url":"nodes/flow-sequence.html#node-flow-sequence-field-delayMs","title":"Wait before firing (milliseconds)","section":"nodes/flow-sequence","text":"How long to pause before this output fires, counted from the previous one. 0 fires it immediately; 1000 is one second. What to put here How long to wait before this output fires, counted from the one before it. Example 1500 Limits 0 or more. Whole numbers, in steps of 100. Wires Socket Direction What to connect In input Whatever should run immediately before this node. Then runs next When tests a condition Unlocks opens an objective Data carries a value A wire only joins two sockets of the same colour, and the editor draws the wire in that colour. That is what the colours are for: match the colours and the connection takes, mismatch them and it will not. The inspector for Sequence . Common m"},{"url":"nodes/fx-claimquest.html#node-fx-claimquest-field-questName","title":"Quest","section":"nodes/fx-claimquest","text":"The identifier of the quest to start next. It must exist in this mod or another installed one. What to put here The identifier of the quest to start next, exactly as that quest names itself. Example meridian-act-two Default empty If you leave it empty There is no quest to claim, so the node does nothing. Watch out The identifier has to match. A name that exists nowhere claims nothing, and the player is left with a finished story and no next chapter. Wires Socket Direction What to connect In input Whatever should run immediately before this node. Out output Whatever should happen after this node runs. Then runs next When tests a condition Unlocks opens an objective Data carries a value A wire"},{"url":"nodes/fx-handbook.html#node-fx-handbook-field-articleId","title":"Article","section":"nodes/fx-handbook","text":"The in-game article the player lands on. Pick a known page, or type any article id. Watch out An identifier that matches no article opens nothing, and the player gets no explanation of why."},{"url":"nodes/fx-handbook.html#node-fx-handbook-field-category","title":"Category","section":"nodes/fx-handbook","text":"The handbook section the article sits under. Wires Socket Direction What to connect In input Whatever should run immediately before this node. Out output Whatever should happen after this node runs. Then runs next When tests a condition Unlocks opens an objective Data carries a value A wire only joins two sockets of the same colour, and the editor draws the wire in that colour. That is what the colours are for: match the colours and the connection takes, mismatch them and it will not. The inspector for Open handbook . Common mistakes The article belongs to another mod. The player does not have it, so the handbook opens on nothing. Point at an article your own mod ships. Messages you might se"},{"url":"nodes/fx-notify.html#node-fx-notify-field-message","title":"Message","section":"nodes/fx-notify","text":"The text on the popup. Type {{data.name}} to insert a value you saved earlier. What to put here One or two sentences is plenty. It sits over the game, not in a journal. Example Payment received: Meridian Capital. Default empty Tags work here Type {{data.something}} to insert a value you saved with Set quest data . If you leave it empty The popup appears with nothing in it. The player sees an empty box and no idea why."},{"url":"nodes/fx-notify.html#node-fx-notify-field-variant","title":"Style","section":"nodes/fx-notify","text":"A notification is a persistent popup; a toast slides in and fades on its own. What to put here Pick how insistent the message should be. Default \"notify\" Limits One of the 2 listed below. Watch out A notification waits for the player to close it. Use a toast for anything they can afford to miss. Choice What it is stored as Notification popup notify Toast toast"},{"url":"nodes/fx-notify.html#node-fx-notify-field-tone","title":"Tone","section":"nodes/fx-notify","text":"Sets the colour and icon: info, success, warning or error. What to put here Match it to what the message means: a success for a payment, a warning for a mistake. Default \"info\" Limits One of the 4 listed below. Choice What it is stored as Info info Success success Warning warning Error error Wires Socket Direction What to connect In input Whatever should run immediately before this node. Out output Whatever should happen after this node runs. Then runs next When tests a condition Unlocks opens an objective Data carries a value A wire only joins two sockets of the same colour, and the editor draws the wire in that colour. That is what the colours are for: match the colours and the connection "},{"url":"nodes/fx-pay.html#node-fx-pay-field-amount","title":"Amount","section":"nodes/fx-pay","text":"Credits deposited into the player's bank account. The hint above is the editor's own wording and it still says \"Credits.\" The money is dollars. That wording is on the list to be corrected. What to put here A whole number of dollars. The fee, the bounty, the settlement. Example 100 Default 100 Limits 0 or more. Decimals are not accepted. If you leave it empty The payment never happens, and nothing tells you. The exported mod skips the whole transaction when the amount is not above zero — no error, no warning, no line in the bank statement. Check this first when a payment does not arrive."},{"url":"nodes/fx-pay.html#node-fx-pay-field-description","title":"Description","section":"nodes/fx-pay","text":"The label on the bank statement line. What to put here The words the player reads on their statement. Write it the way a bank would, because the player reads it as evidence that the job paid out. Example Meridian Capital — contract settlement Default Job payment Limits Technically any text, but keep it short — a bank statement line is only a few words, and the game may cut a long one. If you leave it empty The statement line has no label, so the player sees money appear from nowhere. Watch out This is a good place for a runtime tag if the amount should read differently per player — see Generate and tags ."},{"url":"nodes/fx-pay.html#node-fx-pay-field-fromIBAN","title":"From IBAN","section":"nodes/fx-pay","text":"The sending account, shown in the transfer details. What to put here The account number the money came from. Players who dig into the transfer see it, so it works as a clue. Example DE89370400440532013000 Default empty Limits Any text. The editor does not check that it is a real account number. If you leave it empty The transfer details show no sending account. Watch out The dice button beside this field writes a plausible account number, so you do not have to invent one that looks right."},{"url":"nodes/fx-pay.html#node-fx-pay-field-fromName","title":"From name","section":"nodes/fx-pay","text":"The sender's name on the statement. What to put here Who the player should believe sent the money. A person, a company, or the client's handle from earlier in the story. Example Meridian Capital Default empty If you leave it empty The statement names no sender. Filling in one of From name or From IBAN is enough for the game to attach a sender to the transfer — but a statement with an account number and no name looks unfinished, so fill in both. Watch out Keep this consistent with whoever hired the player. A payment from a name the story never mentioned reads as a mistake, not a mystery. Wires Socket Direction What to connect Required? If left unconnected In input The node that should run imm"},{"url":"nodes/fx-setdata.html#node-fx-setdata-field-key","title":"Key","section":"nodes/fx-setdata","text":"A name you choose, like doorCode. Use the same name later to read this value back. What to put here The name you will use to read this value back. Example doorCode Default empty If you leave it empty The value is stored under no name, so nothing can find it again."},{"url":"nodes/fx-setdata.html#node-fx-setdata-field-value","title":"Value","section":"nodes/fx-setdata","text":"Any text is fine — a word, a number, an address. It is just stored, so nothing here can error. You can also insert a live value by typing {{data.name}} for something you saved earlier. Example 4417 Default empty Tags work here Type {{data.something}} to insert a value you saved with Set quest data . Watch out The name has to match exactly when you read it back. A typo reads as an empty value and nothing warns you. Wires Socket Direction What to connect In input Whatever should run immediately before this node. Out output Whatever should happen after this node runs. Then runs next When tests a condition Unlocks opens an objective Data carries a value A wire only joins two sockets of the same "},{"url":"nodes/fx-shell.html#node-fx-shell-field-command","title":"Command","section":"nodes/fx-shell","text":"The command executed in the player's terminal, as if they had typed it. Tags like {{data.targetIp}} are filled in first. What to put here The command to run. Tags work here, so you can drop in a value you stored earlier. Example nmap {{data.targetIp}} Default empty Tags work here Type {{data.something}} to insert a value you saved with Set quest data . If you leave it empty There is nothing to run, so the node does nothing. Watch out It runs whether or not the player is ready for it. A command that needs an earlier step will fail in front of them. Wires Socket Direction What to connect In input Whatever should run immediately before this node. Out output Whatever should happen after this nod"},{"url":"nodes/fx-withdraw.html#node-fx-withdraw-field-amountMode","title":"Amount type","section":"nodes/fx-withdraw","text":"A fixed sum, or a slice of whatever the player currently has in the bank. What to put here Pick which of the two numbers below this node reads. <b class=\"ui\">Fixed amount</b> reads <b class=\"ui\">Amount</b>. <b class=\"ui\">Percentage of balance</b> reads <b class=\"ui\">Percent</b>. Default \"fixed\" Limits One of the 2 listed below. Watch out Both number fields stay visible whichever you pick, and the one you did not pick is ignored. Check this first when a charge comes out wrong. Choice What it is stored as Fixed amount fixed Percentage of balance percent"},{"url":"nodes/fx-withdraw.html#node-fx-withdraw-field-amount","title":"Amount","section":"nodes/fx-withdraw","text":"Credits taken from the player's account. What to put here The sum to take, in dollars. Example 35 Default 100 Limits 0 or more. If you leave it empty Nothing happens. The charge is skipped with no warning and no line in the bank statement."},{"url":"nodes/fx-withdraw.html#node-fx-withdraw-field-percent","title":"Percent","section":"nodes/fx-withdraw","text":"Percentage of the player's current balance, taken when this node runs. What to put here The share of the player's current balance to take. 10 takes a tenth of whatever they have right now. Default 10 Limits 0 to 100. Watch out The result is rounded to a whole number, so a small balance can produce a charge of zero."},{"url":"nodes/fx-withdraw.html#node-fx-withdraw-field-description","title":"Description","section":"nodes/fx-withdraw","text":"The label on the bank statement line. Example Tool licence — packet sniffer Default \"Purchase\" Limits Technically any text, but keep it short. A statement line is only a few words. If you leave it empty The statement line has no label, so the player sees money vanish from nowhere. Wires Socket Direction What to connect In input Whatever should run immediately before this node. Out output Whatever should happen after this node runs. Then runs next When tests a condition Unlocks opens an objective Data carries a value A wire only joins two sockets of the same colour, and the editor draws the wire in that colour. That is what the colours are for: match the colours and the connection takes, mism"},{"url":"nodes/layout-group.html#node-layout-group-field-label","title":"Name","section":"nodes/layout-group","text":"Shown in the frame's title bar — name the cluster after what it does, e.g. “Act 1: recon”. What to put here The frame's title. Name the cluster after what it does. Example Act 1: the docks Default \"Group\""},{"url":"nodes/layout-group.html#node-layout-group-field-color","title":"Title bar colour","section":"nodes/layout-group","text":"Colour-code your frames however you like — e.g. one colour per act, or per character. It only changes how the frame looks in the editor. What to put here Colour-code your frames however helps: one colour per act, or per character. Default \"#64748b\""},{"url":"nodes/layout-group.html#node-layout-group-field-comment","title":"Comment","section":"nodes/layout-group","text":"A note to future-you about what this cluster does. What to put here A note to future-you about what this cluster does. Default empty Wires This node has no sockets of its own. Then runs next When tests a condition Unlocks opens an objective Data carries a value A wire only joins two sockets of the same colour, and the editor draws the wire in that colour. That is what the colours are for: match the colours and the connection takes, mismatch them and it will not. The inspector for Group frame . Related nodes Sticky note — A comment on the canvas. Story Beat — Plans a story beat. Never runs. ← Reroute Random pick → ↑ back to top HackHub Quest Editor handbook · documents editor build 2026-09-14"},{"url":"nodes/objective.html#node-objective-field-name","title":"Identifier","section":"nodes/objective","text":"A short unique name for this objective so other nodes can refer to it. Lowercase with dashes reads well. Example dock-shipment Default empty If you leave it empty Other nodes have nothing to refer to. Name the objective before you wire anything to it."},{"url":"nodes/objective.html#node-objective-field-description","title":"Shown to the player","section":"nodes/objective","text":"The line shown in the player's quest journal. A clear instruction tends to read well, but any wording that fits your quest works. What to put here Write it as an instruction: what to do, and where. Example Find the shipment manifest on the dock terminal. Default empty Limits Technically any text, but keep it to one line. The journal truncates a long one. If you leave it empty The journal shows a blank task. The player has no idea what they are meant to do."},{"url":"nodes/objective.html#node-objective-field-hint","title":"Hint","section":"nodes/objective","text":"Revealed only if the player asks for help. As gentle or as cryptic as you want it to be. Example The manifest sits on the machine by the gate, not the office."},{"url":"nodes/objective.html#node-objective-field-info","title":"Extra info","section":"nodes/objective","text":"Extra detail in the journal's expanded view. Good for lore or background. What to put here Lore belongs here rather than in the journal line. Example Meridian Capital moved the shipment twice after the strike."},{"url":"nodes/objective.html#node-objective-field-terminalCommand","title":"Suggested command","section":"nodes/objective","text":"Suggested command shown in the journal. It runs nothing — it is a copy-pasteable nudge. Example ssh dock01.meridian.local Watch out It runs nothing on its own. It is a nudge the player can copy, not a shortcut."},{"url":"nodes/objective.html#node-objective-field-hidden","title":"Hidden until unlocked","section":"nodes/objective","text":"Keep the objective out of the journal until another objective unlocks it. Use for twists. What to put here Turn this on to keep the objective out of the journal until another objective unlocks it. Default off Limits On or off. Watch out A hidden objective still has to be reachable. If nothing unlocks it, the player never sees it and the quest stalls. Wires Socket Direction What to connect In input Whatever should run immediately before the objective is handed to the player — usually Quest start or the objective before it. Trigger input The When event node that ticks this objective over. Unlocked by input An objective that has to finish before this one becomes available. On complete output Wh"},{"url":"nodes/trigger-event.html#node-trigger-event-field-event","title":"Game event","section":"nodes/trigger-event","text":"All 92 HackHub events, listed with the details each one carries. Default empty If you leave it empty There is nothing to listen for, so the node never fires."},{"url":"nodes/trigger-event.html#node-trigger-event-field-conditions","title":"Only when","section":"nodes/trigger-event","text":"Leave empty to fire on any occurrence. What to put here Add one clause per thing that has to be true. Default an empty list Watch out The same action can raise more than one event. Check the list for the one that carries the details you need. Wires Socket Direction What to connect When output The objective or branch that should react when the event fires. Then runs next When tests a condition Unlocks opens an objective Data carries a value A wire only joins two sockets of the same colour, and the editor draws the wire in that colour. That is what the colours are for: match the colours and the connection takes, mismatch them and it will not. Step by step: add this node to a quest Find When ev"},{"url":"nodes.html#cat-entry","title":"Quest lifecycle","section":"nodes","text":"Node What it does Quest start entry.start Runs once when the quest begins. Setup goes here. On start & reload entry.load Runs on claim and every load. Listeners go here. On quest complete entry.complete Only runs if the quest completes — with auto-complete off and no Complete button (the default) that never happens. End the story from the last objective instead. On quest abandoned entry.abandon Runs if the player gives up. Cleanup goes here."},{"url":"nodes.html#cat-objective","title":"Objectives","section":"nodes","text":"Node What it does Objective objective A task the player must complete"},{"url":"nodes.html#cat-trigger","title":"Triggers","section":"nodes","text":"Node What it does When event trigger.event React to something the player does"},{"url":"nodes.html#cat-world","title":"World building","section":"nodes","text":"Node What it does Create network world.network Routers, devices, firewalls and ports Firewall rule world.firewall Allow or block a port Change port world.port Open, close, add or remove a port Register domain world.domain Point a hostname at an IP Create database world.database Content for sqlmap and DatabaseManager Place files world.files Drop files on a PC or a remote device Tool response world.toolResponse Script what a recon tool reports"},{"url":"nodes.html#cat-comms","title":"Communication","section":"nodes","text":"Node What it does Dialogue comms.dialogue A conversation with the player — phone call, Kisscord, e-mail or WeeChat"},{"url":"nodes.html#cat-reply","title":"Custom terminal","section":"nodes","text":"Node What it does Manual input reply.input The player types a passphrase"},{"url":"nodes.html#cat-effect","title":"Effects","section":"nodes","text":"Node What it does Pay the player fx.pay Deposit money Charge the player fx.withdraw Withdraw money Notify fx.notify A popup or toast Set quest data fx.setData Store a value for later Claim another quest fx.claimQuest Chain into the next quest Run terminal command fx.shell Execute in the terminal Open handbook fx.handbook Jump to an in-game article"},{"url":"nodes.html#cat-community","title":"Community addons","section":"nodes","text":"Node What it does Give data to an addon world.packData Pick a data shape from an addon and fill it in Addon node pack.node A story node from an addon — find it under Editor Mods"},{"url":"nodes.html#cat-flow","title":"Flow control","section":"nodes","text":"Node What it does Branch flow.branch Split on a condition Wait flow.delay Pause before continuing Reroute flow.reroute Split or tidy a wire Random pick flow.random Choose one option at random Sequence flow.sequence Fire several outputs one after another Debug probe flow.debug Print what is happening here"},{"url":"nodes.html#cat-layout","title":"Layout","section":"nodes","text":"Node What it does Group frame layout.group A named box that moves its nodes Sticky note flow.note A comment on the canvas Story Beat flow.beat Plan a story beat — colour it, preview it ← How a quest works Feature guides → HackHub Quest Editor handbook · documents editor build 2026-09-14.r162 · every figure on these pages is taken from the editor's own source."},{"url":"troubleshooting.html#start-here","title":"What is happening?","section":"troubleshooting","text":"Written in Phase 4."},{"url":"troubleshooting.html#nothing-runs","title":"Nothing happens at all","section":"troubleshooting","text":"Written in Phase 4."},{"url":"troubleshooting.html#objective-never-ticks","title":"The objective never ticks","section":"troubleshooting","text":"Written in Phase 4."},{"url":"troubleshooting.html#cannot-get-in","title":"The player cannot get into the machine","section":"troubleshooting","text":"Written in Phase 4."},{"url":"troubleshooting.html#export-refuses","title":"The export refuses","section":"troubleshooting","text":"Written in Phase 4."},{"url":"troubleshooting.html#faq","title":"Frequently asked","section":"troubleshooting","text":"Written in Phase 4. ← Exporting and installing Glossary and limits → HackHub Quest Editor handbook · documents editor build 2026-09-14.r162 · every figure on these pages is taken from the editor's own source."},{"url":"tutorial.html#tour","title":"The screen, labelled","section":"tutorial","text":"Written in Phase 4."},{"url":"tutorial.html#new-project","title":"Start from a template","section":"tutorial","text":"Written in Phase 4."},{"url":"tutorial.html#add-objective","title":"Add your own objective","section":"tutorial","text":"Written in Phase 4."},{"url":"tutorial.html#wire-trigger","title":"Make it complete","section":"tutorial","text":"Written in Phase 4."},{"url":"tutorial.html#export","title":"Export, install, play","section":"tutorial","text":"Written in Phase 4."},{"url":"tutorial.html#recap","title":"What you built","section":"tutorial","text":"Written in Phase 4. ← Start here How a quest works → HackHub Quest Editor handbook · documents editor build 2026-09-14.r162 · every figure on these pages is taken from the editor's own source."}];
